        // Distribute pupils into 'g' groups as evenly as possible
        val base = pupils / g
        val rem = pupils % g

        // Cost for groups with base+1 pupils (rem groups)
        val costRem = rem * (c1 + c2 * (base + 1) * (base + 1))
        // Cost for groups with base pupils (g - rem groups)
        val costBase = (g - rem) * (c1 + c2 * base * base)

        val total = costRem + costBase
        if (total < minPrice) {
            minPrice = total
        }
    }

