        val basePupilsPerGroup = remainingPupils / totalGroups
        val extraPupils = remainingPupils % totalGroups

        val baseAdultsPerGroup = remainingAdults / totalGroups
        val extraAdults = remainingAdults % totalGroups

        var cost = 0L
        for (i in 0 until totalGroups) {
            val groupSize = 1 + basePupilsPerGroup + baseAdultsPerGroup
