        val totalGroups = groups
        val remainingPupils = pupils
        val minPerGroup = (remainingPupils + totalGroups - 1) / totalGroups
        val maxPerGroup = (n + totalGroups - 1) / totalGroups
        var cost = 0L
        for (x in 1..maxPerGroup) {
            val count = if (x <= minPerGroup) totalGroups else (n - x * (totalGroups - 1) + x - 1) / x
            if (count <= 0) break
            val groupCost = c1 + c2 * (x - 1) * (x - 1)
            cost += groupCost * count
        }
        if (cost < minPrice) {
            minPrice = cost
        }
    }
    println(minPrice)
